def refs():
    return [{**s, "subject": "science", "locator": "細胞分裂、染色體與染色分體、DNA複製、有絲分裂前後的遺傳物質分配", "observedPattern": "公立學校公開生物科試題常以細胞週期圖、染色體數量判讀、分裂階段排序與生長修復情境考查遺傳物質分配；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


