Q = [
    make(1, "有絲分裂對多細胞生物最直接的作用為何？", {"A": "增加細胞數量，支援生長、組織修補與更新", "B": "讓每個子細胞的染色體數量永久加倍", "C": "把兩個不同物種的遺傳物質混合", "D": "只在生物形成配子時才會發生"}, "有絲分裂產生遺傳資訊大致相同的子細胞，細胞數量增加可支援身體長大與受傷組織修補；它不是把染色體數量永久加倍的程序。", "先分辨題目問的是細胞數量、染色體數量還是遺傳組合，再對照有絲分裂的功能。", ["圈出題幹的功能關鍵詞『多細胞生物』。", "連結生長與修補需要增加相似細胞。", "排除染色體永久加倍與物種混合等敘述。", "確認有絲分裂的結果是兩個相近的子細胞。", "所以選 A。"], "easy"),
    make(2, "一個細胞在分裂前先複製 DNA，最合理的解釋是？", {"A": "先複製成兩份，分裂時才能把遺傳物質分配給兩個子細胞", "B": "複製後細胞立刻變成兩個完整個體", "C": "複製會使原本的染色體數量永久變成兩倍", "D": "複製只會增加細胞膜厚度，與分裂無關"}, "分裂前複製 DNA 是為了準備兩份遺傳物質，之後在分裂過程中分配到兩個子細胞；複製本身不等於細胞已完成分裂，也不使染色體套數永久加倍。", "把『複製』和『分離、分裂』拆成不同事件，避免把準備階段當成結果。", ["找出題目要求解釋的是複製的目的。", "確認複製先產生兩份相同的遺傳物質。", "再檢查這兩份物質會在分裂時分給兩個子細胞。", "排除把複製誤當成細胞分裂完成的選項。", "所以選 A。"], "medium"),
    make(3, "某細胞原本有 4 條染色體。DNA 複製完成但尚未分裂時，哪項判斷正確？", {"A": "染色體仍算 4 條，但每條已含兩條相同的染色分體", "B": "染色體變成 8 條，且沒有任何染色分體", "C": "染色體減少為 2 條，因為 DNA 已被複製", "D": "細胞已分成兩個各有 4 條染色體的子細胞"}, "DNA 複製會讓每條染色體形成兩條相同的染色分體；在著絲點尚未分開前，染色體數量仍以著絲點計為 4 條，細胞也尚未完成分裂。", "遇到數量題先確認計數標準，再分辨複製與分離是否已發生。", ["先記下複製前的染色體數量是 4。", "確認複製增加的是每條染色體內的染色分體。", "檢查著絲點尚未分開，所以染色體數量不改變。", "確認尚未胞質分裂，不能說已形成兩個子細胞。", "所以選 A。"], "hard"),
    make(4, "下列哪個順序最符合一般有絲分裂的主要事件？", {"A": "胞質分裂→DNA 複製→染色體排列→染色分體分離", "B": "染色分體分離→DNA 複製→胞質分裂→染色體排列", "C": "DNA 複製→染色體排列→染色分體分離→胞質分裂", "D": "染色體排列→胞質分裂→DNA 複製→染色分體分離"}, "細胞先在分裂前完成 DNA 複製，染色體在細胞中央排列後，姐妹染色分體分開移向兩端，最後胞質分裂形成兩個子細胞。", "把流程題改寫成時間線，依『準備—排列—分離—切開』逐段核對。", ["找出必須先完成的 DNA 複製。", "確認複製後染色體要排列，才有利於平均分配。", "將染色分體分離放在排列之後。", "把胞質分裂放在遺傳物質分配完成之後。", "所以選 C。"], "medium"),
    make(5, "正常有絲分裂完成後，兩個子細胞通常具有何種關係？", {"A": "染色體數量與遺傳資訊大致相同，能維持原組織的功能", "B": "一個子細胞擁有全部染色體，另一個完全沒有", "C": "兩個子細胞必然屬於不同物種", "D": "兩個子細胞都不再含有 DNA"}, "有絲分裂的核心是將複製後的遺傳物質平均分配，使兩個子細胞通常具有相同的染色體數量與大致相同的遺傳資訊。", "先抓『正常』『有絲分裂』『兩個子細胞』三個條件，再檢查是否符合平均分配。", ["確認題目不是在問減數分裂或受精。", "找出正常有絲分裂的分配目標。", "比較兩個子細胞的染色體數量與 DNA。", "排除全有或全無、不同物種與無 DNA 的說法。", "所以選 A。"], "easy"),
    make(6, "若觀察到一個皮膚傷口逐漸長出新的表皮細胞，最合理的推論是？", {"A": "原有表皮細胞透過有絲分裂增加數量，子細胞再分化與排列", "B": "傷口中的每個細胞都直接把染色體數量減半", "C": "新的表皮細胞只能由消化食物在體外組成", "D": "修補傷口必須先讓所有細胞互相交換物種"}, "表皮修補需要增加同類細胞，有絲分裂提供細胞數量；之後細胞仍需依組織位置與功能排列、分化，不能把修補解釋成染色體減半。", "情境題先從生理需求回推細胞事件，再檢查染色體變化是否合理。", ["辨認傷口修補需要的是更多表皮細胞。", "連結有絲分裂可增加細胞數量。", "補上子細胞排列與分化才能恢復組織功能。", "排除染色體減半與物種交換等不相關敘述。", "所以選 A。"], "medium"),
    make(7, "研究者用染色體卡片模擬分裂，發現姐妹染色分體沒有平均分到兩側。最應先擔心哪個結果？", {"A": "兩個子細胞可能得到不同數量或組合的遺傳物質", "B": "所有子細胞一定會立刻變成細菌", "C": "DNA 會因此完全消失且無法被觀察", "D": "細胞會因為卡片不動而自動增加器官數量"}, "染色分體分離的功能是平均分配遺傳物質；若分配不均，子細胞可能得到不同的染色體數量或組合，後續功能也可能受影響。", "模型題要先對照模型動作代表的生物事件，再推論直接後果，不跨越證據過度下結論。", ["確認卡片代表複製後的染色分體。", "找出沒有平均分配這個觀察結果。", "推論兩個子細胞得到的遺傳物質可能不同。", "只說明可由模型支持的直接風險，不臆測特定疾病。", "所以選 A。"], "hard"),
    make(8, "為何染色體在細胞中央排列有助於有絲分裂？", {"A": "可讓兩側紡錘絲較容易把成對的染色分體分開並平均分配", "B": "可讓 DNA 不必複製就直接消失", "C": "可把細胞膜變成細胞壁", "D": "可使子細胞完全不需要遺傳物質"}, "中央排列提供清楚的分配位置，使紡錘絲能牽引姐妹染色分體分開並分到兩側，幫助兩個子細胞取得相近的遺傳物質。", "把結構位置連到它解決的分配問題，不只背階段名稱。", ["確認中央排列發生在染色分體分離之前。", "找出此排列提供對稱的分配基準。", "連結紡錘絲牽引與兩側移動。", "確認目的在平均分配遺傳物質，而非改變細胞膜。", "所以選 A。"], "medium"),
    make(9, "小明說：『DNA 複製後染色體數量立刻變成兩倍，所以分裂前細胞已經有兩套染色體。』哪項回應最適當？", {"A": "不正確；複製增加的是染色分體，著絲點未分開前染色體數量仍按原數計", "B": "正確；只要 DNA 變多，染色體數量必然加倍", "C": "不正確；DNA 複製會讓染色體數量直接減半", "D": "正確；複製後細胞已經完成胞質分裂"}, "染色體數量的判定要看著絲點；DNA 複製後每條染色體含兩條染色分體，但在分離前不能把它直接算成兩條染色體，也尚未完成胞質分裂。", "先拆解同學的兩個主張：DNA 變多與染色體計數，再逐一驗證。", ["標記錯誤主張是把染色分體當成染色體。", "確認複製後著絲點仍相連。", "用著絲點數量判斷染色體數量暫不加倍。", "補充細胞仍未完成胞質分裂。", "所以選 A。"], "hard"),
    make(10, "用模型判斷有絲分裂是否可能產生兩個遺傳物質相近的子細胞時，哪項證據最關鍵？", {"A": "每條染色體先複製，之後姐妹染色分體分開且平均進入兩側", "B": "模型使用的卡片顏色很鮮豔", "C": "細胞圖畫得比原來大", "D": "觀察者記得分裂結果但沒有記錄過程"}, "要支持遺傳物質相近的推論，必須觀察到複製、姐妹染色分體分離與兩側平均分配的連續證據；顏色或圖片大小不能取代分配證據。", "證據題要區分與結論直接相關的操作紀錄，以及只影響外觀的資訊。", ["先寫出要支持的結論是兩個子細胞遺傳物質相近。", "找出結論所需的前提：複製與姐妹分離。", "檢查是否有兩側平均分配的過程紀錄。", "排除顏色、大小與只記結果等無法支持機制的資訊。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
